insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('que-hace-comoda-a-una-vivienda-en-epocas-de-calor','ciudades',array['ambiente','salud']::text[],'¿Qué hace cómoda a una vivienda en épocas de calor?','Investiga qué características de una vivienda, como techo, color, ventanas, sombra y ventilación, hacen que sea más fresca o más calurosa, y mídelo con termómetros.','Análisis','~22 h',22,array['Confort térmico','Calor']::text[],array['investigar','resolver']::text[],'propios',NULL,'arquitectura ingenieria ambiental fisica ingenieria civil ingenieria mecanica diseno estadistica salud publica medicion con instrumentos simples. analisis de causas. diseno de soluciones. interpretacion de datos. termometros o sensores. hoja de calculo. un editor de graficos.',$a27sld${"id": "que-hace-comoda-a-una-vivienda-en-epocas-de-calor", "area": "ciudades", "areas2": ["ambiente", "salud"], "titulo": "¿Qué hace cómoda a una vivienda en épocas de calor?", "resumen": "Investiga qué características de una vivienda, como techo, color, ventanas, sombra y ventilación, hacen que sea más fresca o más calurosa, y mídelo con termómetros.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Confort térmico", "Calor"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Ambiental", "Física", "Ingeniería Civil", "Ingeniería Mecánica", "Diseño", "Estadística", "Salud Pública"], "problema": ["En verano algunas viviendas se vuelven hornos y otras se mantienen soportables sin ventilador. Las diferencias dependen del material del techo, de la sombra, del color de las paredes y de cómo corre el aire.", "Entender estos factores permite proponer mejoras baratas que hagan la vida más cómoda y gasten menos energía."], "desarrollar": ["Elige dos o tres espacios con características distintas y mide durante varios días la temperatura interior a distintas horas, y anota techo, ventanas, color, sombra y ventilación.", "Relaciona las diferencias de temperatura con las características de cada espacio y propón tres cambios de bajo costo, como pintar el techo de claro, poner cortinas o abrir ventilación cruzada."], "ampliaciones": [{"titulo": "Probar un cambio", "aporta": "aplica un cambio sencillo, como cubrir una ventana, y mide el efecto."}, {"titulo": "Costo y ahorro", "aporta": "estima cuánto costaría el cambio y cuánta energía ahorraría."}, {"titulo": "Barrios más cálidos", "aporta": "relaciona tus resultados con la cantidad de árboles y áreas verdes cercanas."}], "objetivos": ["Medir temperaturas con método.", "Relacionar diseño y confort.", "Proponer cambios de bajo costo.", "Probar el efecto de una mejora."], "habilidades": ["Medición con instrumentos simples.", "Análisis de causas.", "Diseño de soluciones.", "Interpretación de datos."], "herramientas": ["Termómetros o sensores.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Mide solo espacios propios o con permiso y evita pruebas con riesgo, como subir al techo sin seguridad.", "No sustituyas la atención de salud en caso de golpes de calor: en olas de calor intensas busca ayuda médica."], "otroSector": "El mismo estudio sirve para colegios, talleres, invernaderos o locales de comercio."}$a27sld$::jsonb,43),
('cuanto-espacio-habitable-necesita-una-familia-segun-el-tamano-de','ciudades',array['sociedad','salud']::text[],'¿Cuánto espacio habitable necesita una familia según el tamaño de su hogar?','Calcula cuánto espacio por persona tiene un hogar según su tamaño y compara con referencias de habitabilidad para entender cuándo hay hacinamiento y qué efecto tiene.','Análisis','~20 h',20,array['Hacinamiento','Espacio']::text[],array['investigar']::text[],'publicos',NULL,'arquitectura sociologia trabajo social estadistica salud publica ingenieria civil psicologia economia lectura de datos censales. calculo de indicadores. analisis social. propuestas de diseno. hoja de calculo. datos abiertos de censos y encuestas. un editor de graficos.',$a28sld${"id": "cuanto-espacio-habitable-necesita-una-familia-segun-el-tamano-de", "area": "ciudades", "areas2": ["sociedad", "salud"], "titulo": "¿Cuánto espacio habitable necesita una familia según el tamaño de su hogar?", "resumen": "Calcula cuánto espacio por persona tiene un hogar según su tamaño y compara con referencias de habitabilidad para entender cuándo hay hacinamiento y qué efecto tiene.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Hacinamiento", "Espacio"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Arquitectura", "Sociología", "Trabajo Social", "Estadística", "Salud Pública", "Ingeniería Civil", "Psicología", "Economía"], "problema": ["Vivir con muy poco espacio por persona afecta el descanso, el estudio, la privacidad y la salud. Pero qué es «suficiente» depende de la cantidad de personas, de cómo se usan los cuartos y de la cultura de cada hogar.", "Medirlo con datos públicos permite ver qué tan extendido es el hacinamiento y a quién afecta más."], "desarrollar": ["Con encuestas o censos públicos, calcula el promedio de personas por cuarto y de metros cuadrados por persona en distintos tipos de hogar y zonas.", "Compara con los criterios de organismos de vivienda, explica qué hogares estarían en situación de hacinamiento y propón estrategias de organización del espacio para casos ficticios."], "ampliaciones": [{"titulo": "Efecto en el estudio", "aporta": "analiza cómo afecta el espacio al rendimiento escolar según estudios públicos."}, {"titulo": "Uso múltiple", "aporta": "diseña cómo un mismo cuarto cumple varias funciones."}, {"titulo": "Cambios a lo largo del tiempo", "aporta": "compara con censos anteriores para ver la tendencia."}], "objetivos": ["Calcular indicadores de espacio.", "Comparar con referencias técnicas.", "Identificar grupos más afectados.", "Proponer estrategias de uso del espacio."], "habilidades": ["Lectura de datos censales.", "Cálculo de indicadores.", "Análisis social.", "Propuestas de diseño."], "herramientas": ["Hoja de cálculo.", "Datos abiertos de censos y encuestas.", "Un editor de gráficos."], "lineamientos": ["Usa datos agregados y casos ficticios; no preguntes ni expongas datos de hogares concretos.", "Evita culpar a las familias: presenta el hacinamiento como un problema de acceso a vivienda."], "otroSector": "El mismo cálculo sirve para estudiar el espacio por persona en aulas, dormitorios, buses o albergues."}$a28sld$::jsonb,44),
('que-problemas-de-infraestructura-aparecen-con-mas-frecuencia-en','ciudades',array['sociedad']::text[],'¿Qué problemas de infraestructura aparecen con más frecuencia en las viviendas de una zona?','Haz un inventario de los problemas visibles de las viviendas de una zona, como humedad, grietas, techos o instalaciones, y descubre cuáles son más frecuentes y por qué.','Investigación','~22 h',22,array['Vivienda','Mantenimiento']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria civil arquitectura trabajo social sociologia estadistica ingenieria ambiental geografia derecho observacion de campo. estadistica descriptiva. investigacion de causas. comunicacion clara. una ficha de registro. hoja de calculo. un editor de guias.',$a29sld${"id": "que-problemas-de-infraestructura-aparecen-con-mas-frecuencia-en", "area": "ciudades", "areas2": ["sociedad"], "titulo": "¿Qué problemas de infraestructura aparecen con más frecuencia en las viviendas de una zona?", "resumen": "Haz un inventario de los problemas visibles de las viviendas de una zona, como humedad, grietas, techos o instalaciones, y descubre cuáles son más frecuentes y por qué.", "tipo": "Investigación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Vivienda", "Mantenimiento"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Arquitectura", "Trabajo Social", "Sociología", "Estadística", "Ingeniería Ambiental", "Geografía", "Derecho"], "problema": ["Las viviendas se deterioran con el tiempo y con el clima, pero muchas familias no tienen cómo arreglarlas ni a quién consultar. Los problemas se repiten en una misma zona por materiales, humedad, terreno o forma de construcción.", "Reconocer los problemas más comunes permite pensar en soluciones colectivas, como guías de mantenimiento."], "desarrollar": ["Con una encuesta anónima o una observación desde la calle, registra los problemas visibles más comunes en viviendas de una zona, sin entrar a propiedades privadas ni anotar direcciones.", "Clasifica los problemas, calcula su frecuencia, investiga sus causas probables y elabora una guía ilustrada de prevención y de qué hacer primero."], "ampliaciones": [{"titulo": "Costos de reparación", "aporta": "estima cuánto cuesta arreglar cada problema típico."}, {"titulo": "Quién puede ayudar", "aporta": "mapea instituciones y programas que apoyan el mejoramiento de vivienda."}, {"titulo": "Prevención", "aporta": "diseña un calendario de mantenimiento sencillo para un hogar."}], "objetivos": ["Registrar problemas con método.", "Calcular frecuencias.", "Investigar causas.", "Crear una guía útil."], "habilidades": ["Observación de campo.", "Estadística descriptiva.", "Investigación de causas.", "Comunicación clara."], "herramientas": ["Una ficha de registro.", "Hoja de cálculo.", "Un editor de guías."], "lineamientos": ["Observa solo desde la vía pública y no entres a propiedades; no registres direcciones ni identifiques viviendas.", "No des consejos de reparación de riesgo estructural: aconseja consultar a un profesional."], "otroSector": "El mismo inventario sirve para evaluar el estado de aulas, de mercados o de espacios comunes de un edificio."}$a29sld$::jsonb,45),
('propuestas-para-mejorar-la-habitabilidad-y-aprovechar-mejor-los','ciudades',array['arte','sociedad']::text[],'Propuestas para mejorar la habitabilidad y aprovechar mejor los espacios pequeños','Diseña soluciones para que un cuarto o una vivienda pequeña funcione mejor, con muebles multiuso, buena luz, orden y privacidad, sin gastar mucho.','Plan','~26 h',26,array['Diseño','Espacios pequeños']::text[],array['crear','resolver']::text[],'ficticios',NULL,'arquitectura diseno ingenieria civil ingenieria industrial trabajo social psicologia ingenieria ambiental sociologia diseno de interiores. planos a escala. pensamiento creativo. estimacion de costos. un programa de dibujo o planos. carton para maqueta. hoja de calculo.',$a30sld${"id": "propuestas-para-mejorar-la-habitabilidad-y-aprovechar-mejor-los", "area": "ciudades", "areas2": ["arte", "sociedad"], "titulo": "Propuestas para mejorar la habitabilidad y aprovechar mejor los espacios pequeños", "resumen": "Diseña soluciones para que un cuarto o una vivienda pequeña funcione mejor, con muebles multiuso, buena luz, orden y privacidad, sin gastar mucho.", "tipo": "Plan", "tiempo": "~26 h", "horas": 26, "etiquetas": ["Diseño", "Espacios pequeños"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Arquitectura", "Diseño", "Ingeniería Civil", "Ingeniería Industrial", "Trabajo Social", "Psicología", "Ingeniería Ambiental", "Sociología"], "problema": ["Muchas familias y estudiantes viven en espacios pequeños donde hay que dormir, estudiar, cocinar y guardar cosas en el mismo lugar. Con un buen diseño se puede ganar comodidad aunque no cambie el tamaño.", "Las ideas útiles suelen ser simples: moverse menos, almacenar en vertical, separar zonas y aprovechar la luz."], "desarrollar": ["Inventa un caso de un espacio pequeño con sus ocupantes y sus necesidades, dibuja el plano con medidas y detecta los problemas de uso, de luz y de almacenamiento.", "Propón una nueva distribución con soluciones concretas de bajo costo, representa antes y después, y estima el costo de cada mejora."], "ampliaciones": [{"titulo": "Maqueta a escala", "aporta": "construye una maqueta de cartón y prueba la distribución."}, {"titulo": "Muebles multiuso", "aporta": "diseña un mueble que cumpla dos o tres funciones."}, {"titulo": "Presupuesto mínimo", "aporta": "diseña la versión más barata posible y compárala con una más completa."}], "objetivos": ["Analizar un espacio pequeño.", "Detectar problemas de uso.", "Proponer una nueva distribución.", "Estimar costos."], "habilidades": ["Diseño de interiores.", "Planos a escala.", "Pensamiento creativo.", "Estimación de costos."], "herramientas": ["Un programa de dibujo o planos.", "Cartón para maqueta.", "Hoja de cálculo."], "lineamientos": ["Trabaja con un caso ficticio o tu propio espacio y no uses imágenes de viviendas ajenas.", "No propongas cambios que comprometan la estructura sin consultar a un profesional."], "otroSector": "El mismo ejercicio sirve para diseñar un puesto de venta, un laboratorio pequeño o un espacio de estudio."}$a30sld$::jsonb,46),
('mapa-de-acceso-al-agua-y-al-saneamiento-en-una-comunidad','ciudades',array['salud','sociedad']::text[],'Mapa de acceso al agua y al saneamiento en una comunidad','Descubre qué zonas de una localidad tienen menos acceso a agua potable y saneamiento, con datos públicos y mapas, y cómo se abastecen quienes no tienen red.','Análisis','~25 h',25,array['Agua potable','Saneamiento']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria civil ingenieria ambiental geografia salud publica trabajo social estadistica sociologia ingenieria sanitaria cartografia. analisis de datos publicos. lectura de indicadores. comunicacion de resultados. un mapa en linea. hoja de calculo. portales de datos abiertos.',$a31sld${"id": "mapa-de-acceso-al-agua-y-al-saneamiento-en-una-comunidad", "area": "ciudades", "areas2": ["salud", "sociedad"], "titulo": "Mapa de acceso al agua y al saneamiento en una comunidad", "resumen": "Descubre qué zonas de una localidad tienen menos acceso a agua potable y saneamiento, con datos públicos y mapas, y cómo se abastecen quienes no tienen red.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Agua potable", "Saneamiento"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Civil", "Ingeniería Ambiental", "Geografía", "Salud Pública", "Trabajo Social", "Estadística", "Sociología", "Ingeniería Sanitaria"], "problema": ["En algunas zonas el agua llega por red, en otras por camión cisterna, pozo o pilón, y el desagüe puede ser alcantarillado, pozo ciego o no existir. Esas diferencias afectan la salud y el costo de vida.", "Un mapa claro de quién tiene qué servicio ayuda a ver las desigualdades y a priorizar inversiones."], "desarrollar": ["Con datos públicos de cobertura de agua y saneamiento por distrito o centro poblado, elabora un mapa por zonas con el porcentaje de acceso a cada servicio.", "Relaciona el mapa con la distancia a fuentes de agua, el precio del agua en cada forma de abastecimiento y los efectos en salud descritos en fuentes oficiales, y concluye qué zonas necesitan atención prioritaria."], "ampliaciones": [{"titulo": "Costo del agua", "aporta": "compara cuánto paga una familia con red frente a una que compra cisterna."}, {"titulo": "Calidad", "aporta": "añade datos públicos de calidad del agua cuando existan."}, {"titulo": "Cambios en el tiempo", "aporta": "compara con datos de años anteriores."}], "objetivos": ["Usar datos públicos de cobertura.", "Mapear el acceso por zonas.", "Relacionar acceso con costo y salud.", "Priorizar zonas."], "habilidades": ["Cartografía.", "Análisis de datos públicos.", "Lectura de indicadores.", "Comunicación de resultados."], "herramientas": ["Un mapa en línea.", "Hoja de cálculo.", "Portales de datos abiertos."], "lineamientos": ["Usa datos agregados y cita las fuentes y fechas; evita señalar viviendas o personas concretas.", "No hagas afirmaciones sobre la calidad del agua sin datos oficiales."], "otroSector": "El mismo mapa sirve para estudiar el acceso a electricidad, a internet o a centros de salud."}$a31sld$::jsonb,47),
('estado-de-la-infraestructura-sanitaria-y-de-las-redes-de-agua-co','ciudades',array['sociedad','derecho']::text[],'Estado de la infraestructura sanitaria y de las redes de agua con información pública','Usa información pública para identificar dónde hay más fugas, cortes o deterioro en las redes de agua y alcantarillado y qué zonas son más afectadas.','Análisis','~24 h',24,array['Redes de agua','Alcantarillado']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria civil ingenieria sanitaria ingenieria ambiental estadistica ciencia de datos derecho economia geografia busqueda de datos publicos. analisis estadistico basico. mapeo. pensamiento critico. hoja de calculo o python. portales de reguladores y empresas de servicios. un mapa en linea.',$a32sld${"id": "estado-de-la-infraestructura-sanitaria-y-de-las-redes-de-agua-co", "area": "ciudades", "areas2": ["sociedad", "derecho"], "titulo": "Estado de la infraestructura sanitaria y de las redes de agua con información pública", "resumen": "Usa información pública para identificar dónde hay más fugas, cortes o deterioro en las redes de agua y alcantarillado y qué zonas son más afectadas.", "tipo": "Análisis", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Redes de agua", "Alcantarillado"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Civil", "Ingeniería Sanitaria", "Ingeniería Ambiental", "Estadística", "Ciencia de Datos", "Derecho", "Economía", "Geografía"], "problema": ["Las redes de agua y desagüe son infraestructura invisible: nadie piensa en ellas hasta que fallan. Las fugas, los cortes y los atoros suelen concentrarse en zonas con tuberías antiguas.", "Las empresas de servicios y organismos reguladores publican algunos datos, y analizarlos permite ver dónde están los puntos críticos."], "desarrollar": ["Reúne datos públicos de una empresa de agua o un regulador sobre cortes, reclamos, fugas o antigüedad de redes, y organízalos por distrito o zona.", "Grafica y mapea los puntos críticos, relaciona con la antigüedad de las redes o con eventos de lluvia, y explica qué hipótesis podrían explicar los patrones."], "ampliaciones": [{"titulo": "Pérdida de agua", "aporta": "estima cuánta agua se pierde en la red según los datos públicos."}, {"titulo": "Costo de reparar", "aporta": "investiga cuánto costaría renovar un tramo de tubería."}, {"titulo": "Comparar empresas", "aporta": "compara indicadores de dos ciudades."}], "objetivos": ["Buscar y organizar datos públicos.", "Mapear puntos críticos.", "Formular hipótesis sobre las causas.", "Comunicar los resultados."], "habilidades": ["Búsqueda de datos públicos.", "Análisis estadístico básico.", "Mapeo.", "Pensamiento crítico."], "herramientas": ["Hoja de cálculo o Python.", "Portales de reguladores y empresas de servicios.", "Un mapa en línea."], "lineamientos": ["Usa solo información pública y distingue entre datos y suposiciones; no acuses a empresas o autoridades sin sustento.", "Cita las fuentes y las fechas."], "otroSector": "El mismo análisis sirve para redes de electricidad, de gas, de internet o de transporte."}$a32sld$::jsonb,48),
('que-tan-accesibles-son-los-servicios-basicos-en-tu-entorno','ciudades',array['sociedad']::text[],'¿Qué tan accesibles son los servicios básicos en tu entorno?','Evalúa qué tan fácil es acceder en tu entorno a agua, electricidad, saneamiento, internet, recojo de residuos y transporte, y qué servicios fallan más.','Análisis','~18 h',18,array['Servicios básicos','Acceso']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia ingenieria civil economia geografia estadistica ingenieria ambiental salud publica diseno de encuestas. analisis de datos. redaccion clara. pensamiento critico. un formulario anonimo. hoja de calculo. un editor de infografias.',$a33sld${"id": "que-tan-accesibles-son-los-servicios-basicos-en-tu-entorno", "area": "ciudades", "areas2": ["sociedad"], "titulo": "¿Qué tan accesibles son los servicios básicos en tu entorno?", "resumen": "Evalúa qué tan fácil es acceder en tu entorno a agua, electricidad, saneamiento, internet, recojo de residuos y transporte, y qué servicios fallan más.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Servicios básicos", "Acceso"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería Civil", "Economía", "Geografía", "Estadística", "Ingeniería Ambiental", "Salud Pública"], "problema": ["Los servicios básicos no se reparten igual: en algunas zonas hay luz y agua todo el día, en otras hay cortes, y algunos servicios simplemente no llegan. Esas diferencias afectan la vida cotidiana de formas muy distintas.", "Un diagnóstico simple, hecho con observación y encuestas anónimas, permite ver qué falta y qué falla en un entorno concreto."], "desarrollar": ["Define una ficha con los servicios básicos y criterios como disponibilidad, calidad, continuidad y costo, y aplícala con encuestas anónimas a una muestra pequeña de vecinos de una zona.", "Resume los resultados con un semáforo por servicio, indica cuáles son más críticos y escribe recomendaciones y a quién podría dirigirse cada reclamo."], "ampliaciones": [{"titulo": "Comparar zonas", "aporta": "compara dos zonas distintas y explica las diferencias."}, {"titulo": "Reclamos", "aporta": "elabora una guía de cómo presentar un reclamo para cada servicio."}, {"titulo": "Costo mensual", "aporta": "calcula cuánto cuesta cada servicio en un hogar típico."}], "objetivos": ["Diseñar una ficha de diagnóstico.", "Aplicarla con consentimiento.", "Resumir en un semáforo.", "Redactar recomendaciones."], "habilidades": ["Diseño de encuestas.", "Análisis de datos.", "Redacción clara.", "Pensamiento crítico."], "herramientas": ["Un formulario anónimo.", "Hoja de cálculo.", "Un editor de infografías."], "lineamientos": ["La encuesta debe ser anónima y voluntaria, sin direcciones exactas; presenta los resultados como tendencias de una muestra pequeña.", "No señales a personas ni a empresas concretas sin evidencia."], "otroSector": "El mismo diagnóstico sirve para un campus, un colegio, un mercado o una comunidad rural."}$a33sld$::jsonb,49),
('un-mapa-de-los-puntos-donde-se-acumula-agua-despues-de-las-lluvi','ciudades',array['ambiente','sociedad']::text[],'Un mapa de los puntos donde se acumula agua después de las lluvias','Identifica dónde se empoza el agua en tu zona cuando llueve, por qué ocurre y qué efectos tiene en el tránsito, las viviendas y la salud.','Análisis','~22 h',22,array['Drenaje','Escorrentía']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria civil ingenieria ambiental geografia ingenieria sanitaria arquitectura estadistica ingenieria de sistemas trabajo social cartografia basica. observacion de campo. analisis de causas. propuestas de solucion. un mapa en linea. una ficha de registro. datos publicos de altitud.',$a34sld${"id": "un-mapa-de-los-puntos-donde-se-acumula-agua-despues-de-las-lluvi", "area": "ciudades", "areas2": ["ambiente", "sociedad"], "titulo": "Un mapa de los puntos donde se acumula agua después de las lluvias", "resumen": "Identifica dónde se empoza el agua en tu zona cuando llueve, por qué ocurre y qué efectos tiene en el tránsito, las viviendas y la salud.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Drenaje", "Escorrentía"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Ingeniería Ambiental", "Geografía", "Ingeniería Sanitaria", "Arquitectura", "Estadística", "Ingeniería de Sistemas", "Trabajo Social"], "problema": ["En muchas ciudades las pistas y veredas se inundan o se llenan de charcos con poca lluvia. Esos puntos suelen repetirse, pero casi nunca se registran y por eso se resuelven tarde.", "En ciudades con lluvias escasas, como Lima, el problema es mayor porque la infraestructura de drenaje se diseña poco, y un evento fuerte genera grandes daños."], "desarrollar": ["Recopila información de vecinos y de observación, tras una lluvia o con fotos de archivos públicos, sobre dónde se acumula agua, cuánto tiempo y qué impacto tiene, y ubícalos en un mapa.", "Relaciona esos puntos con la pendiente, los desagües pluviales y el tipo de superficie, y propón qué intervención sencilla, como una rejilla o un cambio de nivel, resolvería cada tipo de punto."], "ampliaciones": [{"titulo": "Relación con la pendiente", "aporta": "usa un mapa de altitudes para entender por qué se acumula."}, {"titulo": "Efecto en el tránsito", "aporta": "estima cuánto tiempo se pierde por los puntos más afectados."}, {"titulo": "Alerta temprana", "aporta": "diseña un aviso simple para que los vecinos reporten los puntos críticos."}], "objetivos": ["Recopilar y ubicar puntos de acumulación.", "Entender sus causas.", "Mapear con método.", "Proponer soluciones."], "habilidades": ["Cartografía básica.", "Observación de campo.", "Análisis de causas.", "Propuestas de solución."], "herramientas": ["Un mapa en línea.", "Una ficha de registro.", "Datos públicos de altitud."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No te acerques a zonas inundadas ni a cables; observa desde un lugar seguro y no entres a propiedades.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo mapa sirve para registrar baches, basura, cables caídos o árboles en riesgo."}$a34sld$::jsonb,50),
('que-tan-preparada-esta-la-infraestructura-de-drenaje-de-una-zona','ciudades',array['ambiente','ciencias']::text[],'¿Qué tan preparada está la infraestructura de drenaje de una zona para lluvias intensas?','Estima con cálculos simples cuánta agua generaría una lluvia fuerte en una zona y si los desagües, cunetas y canales disponibles podrían manejarla.','Simulación','~26 h',26,array['Drenaje','Lluvias']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria civil ingenieria sanitaria ingenieria ambiental matematica fisica geografia estadistica ciencia de datos calculo hidrologico basico. lectura de datos climaticos. modelado en hoja de calculo. pensamiento critico. hoja de calculo. datos publicos de precipitacion. un mapa en linea.',$a35sld${"id": "que-tan-preparada-esta-la-infraestructura-de-drenaje-de-una-zona", "area": "ciudades", "areas2": ["ambiente", "ciencias"], "titulo": "¿Qué tan preparada está la infraestructura de drenaje de una zona para lluvias intensas?", "resumen": "Estima con cálculos simples cuánta agua generaría una lluvia fuerte en una zona y si los desagües, cunetas y canales disponibles podrían manejarla.", "tipo": "Simulación", "tiempo": "~26 h", "horas": 26, "etiquetas": ["Drenaje", "Lluvias"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Civil", "Ingeniería Sanitaria", "Ingeniería Ambiental", "Matemática", "Física", "Geografía", "Estadística", "Ciencia de Datos"], "problema": ["Cuando llueve más de lo habitual, el agua busca el camino más corto y rápido. Si los desagües y pendientes no están preparados, se desborda y causa daños.", "Un cálculo básico, como el método racional, permite estimar cuánta agua llega y compararla con la capacidad de la infraestructura."], "desarrollar": ["Elige un área pequeña, mide su superficie y los materiales que cubren el suelo, y con datos públicos de lluvias de tu zona estima el caudal que generaría una lluvia intensa con el método racional.", "Compara ese caudal con la capacidad aproximada de los desagües o cunetas visibles, concluye si hay riesgo de desborde y explica las limitaciones de tu cálculo."], "ampliaciones": [{"titulo": "Distintas lluvias", "aporta": "repite el cálculo para lluvias de distinta intensidad."}, {"titulo": "Efecto de áreas verdes", "aporta": "estima cuánto se reduce el caudal si se reemplaza cemento por áreas verdes."}, {"titulo": "Hoja de cálculo reutilizable", "aporta": "crea una plantilla para que otros estimen el caudal en su zona."}], "objetivos": ["Aplicar un método de cálculo simple.", "Usar datos públicos de lluvia.", "Comparar con la capacidad de drenaje.", "Reconocer las limitaciones."], "habilidades": ["Cálculo hidrológico básico.", "Lectura de datos climáticos.", "Modelado en hoja de cálculo.", "Pensamiento crítico."], "herramientas": ["Hoja de cálculo.", "Datos públicos de precipitación.", "Un mapa en línea."], "lineamientos": ["Aclara que es un cálculo simplificado y no sustituye un estudio técnico; no lo uses para decidir sobre seguridad de construcciones.", "Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro."], "otroSector": "El mismo cálculo sirve para planificar techos que recolectan agua de lluvia o jardines que absorben escorrentía."}$a35sld$::jsonb,51),
('como-usa-la-gente-un-parque-o-una-plaza','ciudades',array['sociedad']::text[],'¿Cómo usa la gente un parque o una plaza?','Observa durante varios días cómo usan las personas un parque o plaza, quiénes lo visitan, a qué hora y para qué, y qué zonas se aprovechan más o menos.','Investigación','~20 h',20,array['Uso del espacio','Observación']::text[],array['investigar']::text[],'propios',NULL,'sociologia arquitectura geografia psicologia trabajo social estadistica antropologia diseno observacion sistematica. registro de datos. visualizacion espacial. analisis cualitativo. una ficha de conteo. un plano del parque. hoja de calculo.',$a36sld${"id": "como-usa-la-gente-un-parque-o-una-plaza", "area": "ciudades", "areas2": ["sociedad"], "titulo": "¿Cómo usa la gente un parque o una plaza?", "resumen": "Observa durante varios días cómo usan las personas un parque o plaza, quiénes lo visitan, a qué hora y para qué, y qué zonas se aprovechan más o menos.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Uso del espacio", "Observación"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Sociología", "Arquitectura", "Geografía", "Psicología", "Trabajo Social", "Estadística", "Antropología", "Diseño"], "problema": ["Un espacio público puede estar lleno o vacío, y no siempre por lo bonito que sea. La gente lo usa según la sombra, la seguridad, los bancos, los juegos, la cercanía y los horarios.", "Observar con método muestra quién usa cada parte y quién queda fuera, y da pistas para mejorarlo."], "desarrollar": ["Elige un parque o plaza, divídelo en zonas y registra en varios momentos del día cuántas personas hay en cada zona, qué hacen y de qué grupos parecen ser, sin anotar datos personales.", "Genera un mapa de calor con los usos, identifica las zonas más y menos usadas, y relaciona el resultado con la sombra, los bancos, la iluminación y la limpieza."], "ampliaciones": [{"titulo": "Fin de semana frente a semana", "aporta": "compara cómo cambia el uso."}, {"titulo": "Conversaciones breves", "aporta": "pregunta a cinco usuarios por qué eligen ese lugar."}, {"titulo": "Quién no viene", "aporta": "investiga qué grupos casi no usan el espacio y por qué."}], "objetivos": ["Observar con método.", "Registrar usos y zonas.", "Construir un mapa de uso.", "Relacionar el uso con el diseño."], "habilidades": ["Observación sistemática.", "Registro de datos.", "Visualización espacial.", "Análisis cualitativo."], "herramientas": ["Una ficha de conteo.", "Un plano del parque.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen.", "Los grupos que registres son categorías generales, no datos individuales."], "otroSector": "El mismo método sirve para observar el uso de una biblioteca, un patio escolar o una sala de espera."}$a36sld$::jsonb,52),
('mobiliario-urbano-hay-suficientes-bancas-basureros-y-sombra','ciudades',array['sociedad','ambiente']::text[],'Mobiliario urbano: ¿hay suficientes bancas, basureros y sombra?','Inventaría el mobiliario urbano de una zona, como bancas, basureros, bebederos y sombra, mapea dónde faltan y propone cómo repartirlos mejor.','Análisis','~18 h',18,array['Mobiliario urbano','Espacios públicos']::text[],array['investigar','resolver']::text[],'propios',NULL,'arquitectura diseno ingenieria civil ingenieria ambiental geografia sociologia trabajo social estadistica inventario en campo. cartografia basica. analisis espacial. diseno de propuestas. una ficha de inventario. un mapa en linea. hoja de calculo.',$a37sld${"id": "mobiliario-urbano-hay-suficientes-bancas-basureros-y-sombra", "area": "ciudades", "areas2": ["sociedad", "ambiente"], "titulo": "Mobiliario urbano: ¿hay suficientes bancas, basureros y sombra?", "resumen": "Inventaría el mobiliario urbano de una zona, como bancas, basureros, bebederos y sombra, mapea dónde faltan y propone cómo repartirlos mejor.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Mobiliario urbano", "Espacios públicos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Diseño", "Ingeniería Civil", "Ingeniería Ambiental", "Geografía", "Sociología", "Trabajo Social", "Estadística"], "problema": ["Bancas, basureros, bebederos, paraderos con techo y luminarias hacen que un lugar sea usable y cómodo, pero no siempre están donde se necesitan. Algunas calles tienen de sobra y otras nada.", "Un inventario sencillo muestra dónde hay carencia y a quiénes afecta más."], "desarrollar": ["Recorre una zona y registra cada elemento de mobiliario urbano con su tipo, estado y ubicación aproximada, y mide cada cuántos metros hay una banca o un basurero.", "Mapea las carencias, compara con referencias de distancias recomendadas, y propón una distribución mejor con un presupuesto aproximado."], "ampliaciones": [{"titulo": "Por usuarios", "aporta": "analiza el mobiliario según las necesidades de personas mayores y niños."}, {"titulo": "Estado y mantenimiento", "aporta": "añade qué elementos están rotos o sucios."}, {"titulo": "Diseño propio", "aporta": "diseña una banca o un paradero con materiales económicos."}], "objetivos": ["Inventariar mobiliario urbano.", "Medir distancias entre elementos.", "Detectar carencias.", "Proponer una distribución."], "habilidades": ["Inventario en campo.", "Cartografía básica.", "Análisis espacial.", "Diseño de propuestas."], "herramientas": ["Una ficha de inventario.", "Un mapa en línea.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo inventario sirve para señalización, para luminarias o para áreas verdes."}$a37sld$::jsonb,53),
('puntos-de-encuentro-comunitario-donde-se-junta-tu-comunidad','ciudades',array['sociedad']::text[],'Puntos de encuentro comunitario: ¿dónde se junta tu comunidad?','Identifica los lugares donde se reúne la gente de tu barrio, como losas deportivas, mercados, parques o locales comunales, y qué los hace funcionar como puntos de encuentro.','Investigación','~18 h',18,array['Comunidad','Encuentro']::text[],array['investigar']::text[],'propios',NULL,'sociologia trabajo social arquitectura geografia antropologia psicologia comunicaciones educacion observacion cualitativa. encuestas breves. mapeo comunitario. comunicacion de resultados. un formulario anonimo. un mapa en linea. una ficha de descripcion.',$a38sld${"id": "puntos-de-encuentro-comunitario-donde-se-junta-tu-comunidad", "area": "ciudades", "areas2": ["sociedad"], "titulo": "Puntos de encuentro comunitario: ¿dónde se junta tu comunidad?", "resumen": "Identifica los lugares donde se reúne la gente de tu barrio, como losas deportivas, mercados, parques o locales comunales, y qué los hace funcionar como puntos de encuentro.", "tipo": "Investigación", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Comunidad", "Encuentro"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Sociología", "Trabajo Social", "Arquitectura", "Geografía", "Antropología", "Psicología", "Comunicaciones", "Educación"], "problema": ["Un barrio es más que viviendas: también son los lugares donde sus habitantes se encuentran, conversan y organizan actividades. Cuando esos lugares faltan o no funcionan, la vida comunitaria se debilita.", "Reconocerlos permite cuidarlos y ver dónde faltan."], "desarrollar": ["Con una encuesta breve y anónima y con observación, identifica cuáles son los lugares de encuentro de tu barrio, qué actividades ocurren, en qué horarios y quiénes los usan.", "Haz un mapa de esos lugares, descríbelos y evalúa qué condiciones los hacen funcionar, como sombra, seguridad o cercanía, y qué zonas no tienen ninguno."], "ampliaciones": [{"titulo": "Lugares perdidos", "aporta": "investiga qué espacios dejaron de usarse y por qué."}, {"titulo": "Distintas edades", "aporta": "compara los puntos de encuentro de jóvenes, adultos y mayores."}, {"titulo": "Calendario", "aporta": "arma un calendario de actividades de la comunidad."}], "objetivos": ["Identificar puntos de encuentro.", "Describir su uso.", "Mapearlos.", "Detectar zonas sin espacios de encuentro."], "habilidades": ["Observación cualitativa.", "Encuestas breves.", "Mapeo comunitario.", "Comunicación de resultados."], "herramientas": ["Un formulario anónimo.", "Un mapa en línea.", "Una ficha de descripción."], "lineamientos": ["La participación debe ser voluntaria y anónima; no registres datos personales ni conflictos de personas concretas.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo estudio sirve para entender los espacios de reunión de una universidad, un colegio o una organización."}$a38sld$::jsonb,54),
('espacios-publicos-subutilizados-diagnostico-y-recuperacion','ciudades',array['sociedad','arte']::text[],'Espacios públicos subutilizados: diagnóstico y recuperación','Identifica un espacio público poco usado en tu barrio, entiende por qué está abandonado y diseña una propuesta para devolverle vida, con la participación de quienes viven cerca.','Plan','3 a 5 semanas',25,array['Espacios vacíos','Recuperación']::text[],array['investigar','crear']::text[],'propios',NULL,'arquitectura sociologia diseno geografia ingenieria civil trabajo social ingenieria ambiental economia diagnostico espacial. entrevistas. diseno participativo. planificacion de proyectos. un plano o croquis. una guia de entrevista. un editor de presentaciones.',$a39sld${"id": "espacios-publicos-subutilizados-diagnostico-y-recuperacion", "area": "ciudades", "areas2": ["sociedad", "arte"], "titulo": "Espacios públicos subutilizados: diagnóstico y recuperación", "resumen": "Identifica un espacio público poco usado en tu barrio, entiende por qué está abandonado y diseña una propuesta para devolverle vida, con la participación de quienes viven cerca.", "tipo": "Plan", "tiempo": "3 a 5 semanas", "horas": 25, "etiquetas": ["Espacios vacíos", "Recuperación"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Sociología", "Diseño", "Geografía", "Ingeniería Civil", "Trabajo Social", "Ingeniería Ambiental", "Economía"], "problema": ["Hay terrenos, plazas o parques cerrados, sucios o vacíos que podrían ser lugares valiosos. Suelen estar así por falta de mantenimiento, inseguridad, mala ubicación o porque nadie les asignó un uso.", "Entender las razones permite proponer cambios que sí funcionen."], "desarrollar": ["Elige un espacio poco usado, observa su estado y sus usos durante varios días, y conversa con cinco vecinos sobre por qué creen que no se usa y qué les gustaría ahí.", "Diagnostica las causas, diseña una propuesta con actividades y mejoras sencillas, estima su costo y define cómo se mantendría en el tiempo."], "ampliaciones": [{"titulo": "Usos temporales", "aporta": "propón una actividad temporal, como una feria o un cine al aire libre, para probar el interés."}, {"titulo": "Aliados", "aporta": "identifica instituciones o grupos que podrían ayudar."}, {"titulo": "Seguimiento", "aporta": "diseña indicadores para saber si la propuesta funciona."}], "objetivos": ["Diagnosticar un espacio subutilizado.", "Escuchar a la comunidad.", "Diseñar una propuesta de recuperación.", "Pensar en su sostenibilidad."], "habilidades": ["Diagnóstico espacial.", "Entrevistas.", "Diseño participativo.", "Planificación de proyectos."], "herramientas": ["Un plano o croquis.", "Una guía de entrevista.", "Un editor de presentaciones."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No inicies cambios físicos ni ocupes terrenos: la propuesta es una idea que debe ser conversada con la autoridad y los vecinos.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo proceso sirve para recuperar un aula, un local comunal o un edificio vacío."}$a39sld$::jsonb,55)
